/**
 * Only design directions are generated by the LLM. Theme palettes are computed
 * and checked locally by palette.ts. WebLLM requires the schema as a STRING.
 */
export const THEME_RESPONSE_SCHEMA = JSON.stringify({
  type: 'object',
  properties: {
    name: { type: 'string' },
    description: { type: 'string' },
    accent: { type: 'string' },
    neutral: { type: 'string' },
    contrast: { type: 'string', enum: ['soft', 'balanced', 'high'] },
    darkStyle: { type: 'string', enum: ['black', 'charcoal', 'tinted'] },
    radius: { type: 'integer' },
  },
  required: ['name', 'description', 'accent', 'neutral', 'contrast', 'darkStyle', 'radius'],
  additionalProperties: false,
});

export const THEME_RESPONSE_FORMAT = {
  type: 'json_object' as const,
  schema: THEME_RESPONSE_SCHEMA,
};
